const lessons=[{"sentences":[{"speaker":"A","text":"Please listen carefully to this important update regarding our office facilities today.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.224083333333334},{"speaker":"A","text":"Maintenance staff will temporarily close the third floor meeting rooms for urgent electrical repairs.","position":2,"audioStartSeconds":5.424083333333333,"audioEndSeconds":11.507333333333333},{"speaker":"A","text":"All scheduled afternoon discussions must move to the second floor conference area instead.","position":3,"audioStartSeconds":11.707333333333333,"audioEndSeconds":17.403208333333332},{"speaker":"A","text":"Our technical team expects the necessary wiring work to finish by late afternoon.","position":4,"audioStartSeconds":17.603208333333335,"audioEndSeconds":23.195958333333333},{"speaker":"A","text":"We apologize for any temporary inconvenience caused while our facilities improve.","position":5,"audioStartSeconds":23.395958333333333,"audioEndSeconds":28.834125},{"speaker":"A","text":"Please contact the reception desk if your team requires additional projector equipment.","position":6,"audioStartSeconds":29.034125,"audioEndSeconds":34.498041666666666},{"speaker":"A","text":"Thank you for your cooperation and patience during this routine maintenance period.","position":7,"audioStartSeconds":34.69804166666667,"audioEndSeconds":39.72379166666666},{"speaker":"A","text":"Attention all staff members because we have a quick update about temporary desk assignments.","role":"section-start","position":8,"audioStartSeconds":44.72379166666666,"audioEndSeconds":50.368125},{"speaker":"A","text":"The main marketing sector requires deep cleaning because of unexpected carpet water damage.","position":9,"audioStartSeconds":50.568125,"audioEndSeconds":56.508875},{"speaker":"A","text":"Marketing employees should set up their laptops on the vacant tables near the cafeteria.","position":10,"audioStartSeconds":56.708875,"audioEndSeconds":62.275875},{"speaker":"A","text":"Human resources arranged these temporary workstations so your daily projects continue without delay.","position":11,"audioStartSeconds":62.475875,"audioEndSeconds":68.97070833333333},{"speaker":"A","text":"Cleaning crews will finish scrubbing the affected carpet area by tomorrow morning.","position":12,"audioStartSeconds":69.17070833333334,"audioEndSeconds":74.18358333333333},{"speaker":"A","text":"Please remember to secure your personal belongings before leaving your permanent desks.","position":13,"audioStartSeconds":74.38358333333333,"audioEndSeconds":79.62845833333333},{"speaker":"A","text":"Team supervisors will send an email confirmation when regular seating arrangements resume.","position":14,"audioStartSeconds":79.82845833333333,"audioEndSeconds":85.65325}],"questions":[{"prompt":"What is the main purpose of the first announcement?","options":["To announce room closures for repairs.","To introduce new cleaning staff members.","To request feedback on office facilities."],"answer":"A","evidenceSentence":2,"evidence":"Maintenance staff will temporarily close the third floor meeting rooms","explanation":"Thông báo đầu tiên nêu rõ các phòng họp tầng ba sẽ tạm đóng cửa để sửa chữa điện."},{"prompt":"Where should staff hold their afternoon discussions today?","options":["In the main cafeteria.","On the second floor conference area.","At the reception desk lounge."],"answer":"B","evidenceSentence":3,"evidence":"All scheduled afternoon discussions must move to the second floor conference area instead.","explanation":"Các cuộc họp buổi chiều được chuyển đến khu vực hội nghị ở tầng hai."},{"prompt":"What should teams do if they need extra equipment?","options":["Call the maintenance supervisor.","Email the technical team directly.","Contact the reception desk."],"answer":"C","evidenceSentence":6,"evidence":"Please contact the reception desk if your team requires additional projector equipment.","explanation":"Nhân viên được hướng dẫn liên hệ với quầy lễ tân nếu cần thiết bị máy chiếu bổ sung."},{"prompt":"Why are desk assignments temporarily changing in the second announcement?","options":["Carpet water damage requires cleaning.","New furniture is arriving today.","The office is expanding its team."],"answer":"A","evidenceSentence":9,"evidence":"The main marketing sector requires deep cleaning because of unexpected carpet water damage.","explanation":"Khu vực marketing cần làm sạch sâu do thảm bị hư hại do nước."},{"prompt":"Where should marketing employees sit temporarily?","options":["In the third floor meeting rooms.","Near the cafeteria vacant tables.","Inside the human resources office."],"answer":"B","evidenceSentence":10,"evidence":"Marketing employees should set up their laptops on the vacant tables near the cafeteria.","explanation":"Nhân viên marketing được yêu cầu làm việc tại các bàn trống gần khu vực căng tin."},{"prompt":"When will cleaning of the affected carpet area be completed?","options":["By tomorrow morning.","Late this afternoon.","Next week Monday morning."],"answer":"A","evidenceSentence":12,"evidence":"Cleaning crews will finish scrubbing the affected carpet area by tomorrow morning.","explanation":"Đội vệ sinh sẽ hoàn tất việc làm sạch khu vực thảm bị ảnh hưởng vào sáng mai."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
